=UPDATE lojas_confiaveis SET ultima_varredura = NOW(), produtos_ultima = {{ $json.produtos_total }}, ofertas_ultima = {{ $json.com_oferta }}, ultimo_erro = {{ $json.ultimo_erro_sql }}, official_store_id = COALESCE(official_store_id, {{ $json.official_store_id_sql }}), owner_id = COALESCE(owner_id, {{ $json.owner_id_sql }}), storefront_id = COALESCE(storefront_id, {{ $json.storefront_id_sql }}) WHERE slug = '{{ $json.slug }}' RETURNING slug;